def render(value, /, prefix="", *, upper=False):
    result = prefix + str(value)
    return result.upper() if upper else result

def combine(a, b, *, sep=":"):
    return a + sep + b

values = ["left", "right"]
options = {"sep": "/"}
result = combine(*values, **options)
# "left/right"; combine(*values, a="extra") -> TypeError

def squares(n):
    for value in range(n):
        yield value * value
